function 读取技能效果持续系数_V1(效果 = {}) {
  const 持续 = Math.max(1, Number(效果?.持续回合 ?? 1));
  if (
    String(效果?.原型 || '').trim() === '状态施加' &&
    状态施加状态分类矩阵_V1.硬控封禁类.includes(String(效果?.状态 || '').trim())
  ) {
    if (持续 <= 1) return 1;
    if (持续 === 2) return 2.5;
    if (持续 === 3) return 4.5;
    return 4.5 + (持续 - 3) * 2;
  }
  return 持续 <= 1 ? 1 : 持续 === 2 ? 1.45 : 持续 === 3 ? 1.8 : 1.8 + (持续 - 3) * 0.25;
}

