  魂力枯竭: (目标, 效果) => `使${目标}魂力枯竭，${转译状态施加数值说明_V1('魂力枯竭', 效果)}`,
  僵直: (目标, 效果) => `使${目标}僵直，${转译状态施加数值说明_V1('僵直', 效果)}`,
