  if (等级 <= 1 && 缺少基础社交 && !有魂环) return true;
  return 等级 <= 1 && 年龄 <= 0 && (!武魂名 || 武魂名 === '无' || 武魂名.includes('待补全')) && !有魂灵 && !有魂环;
